select 'quienes-somos', null, 'quienes-somos', 'Quiénes somos', 'Quiénes somos', $json$[{"t":"p","text":"Federación Colombiana de Ganaderos: gremio sin ánimo de lucro que administra el Fondo Nacional del Ganado y representa a los productores bovinos del país."},{"t":"cifras","data":{"titulo":"","columnas":"3","items":[{"valor":"1963","etiqueta":"Año de fundación","nota":""},{"valor":"4","etiqueta":"Frentes del gremio","nota":""},{"valor":"2009","etiqueta":"País libre de aftosa","nota":""}]}},{"t":"h2","text":"Lo que nos guía"},{"t":"cita","data":{"texto":"Representar y promover el desarrollo sostenible y competitivo de la ganadería bovina colombiana.","autor":"Misión","cargo":"","imagen":""}},{"t":"caracteristicas","data":{"columnas":"3","items":[{"icono":"crecimiento","titulo":"Visión","texto":"Ser el gremio referente de la ganadería en Colombia, reconocido por su gestión, innovación y cercanía con los productores."},{"icono":"corazon","titulo":"Valores","texto":"Transparencia, servicio, sostenibilidad y compromiso con las comunidades ganaderas del país."},{"icono":"balanza","titulo":"Buen gobierno","texto":"Gestión institucional bajo el Código de Buen Gobierno y control ciudadano permanente."}]}},{"t":"h2","text":"Nuestra historia"},{"t":"cronologia","data":{"estilo":"linea","items":[{"fecha":"1963","titulo":"Nace FEDEGÁN","texto":"Por decisión del IX Congreso Nacional de Ganaderos se crea la Federación como gremio sin ánimo de lucro."},{"fecha":"1993","titulo":"Leyes 89 y 101","texto":"Nacen la cuota de fomento ganadero y lechero, el Fondo Nacional del Ganado y la base de los fondos de estabilización."},{"fecha":"1995","titulo":"Fomento al consumo","texto":"Comienzan las donaciones de carne y leche a instituciones que atienden población vulnerable."},{"fecha":"1997","titulo":"Erradicación de la aftosa","texto":"La Ley 395 declara de interés nacional la erradicación de la fiebre aftosa."},{"fecha":"2006","titulo":"PEGA 2019","texto":"FEDEGÁN pone en marcha el Plan Estratégico de la Ganadería y se celebra el primer Día Nacional del Ganadero."},{"fecha":"2009","titulo":"País libre de aftosa","texto":"La última certificación completa el estatus de libre con vacunación en todo el territorio."}]}},{"t":"h2","text":"Lo que hacemos"},{"t":"cards","data":{"columnas":4,"items":[{"titulo":"FEDEGÁN","texto":"Representación gremial, fortalecimiento regional y cámaras ganaderas.","imagen":"/locales/programas.jpg","enlace":"/seccion/programas/programa/fedegan","boton":"Conocer"},{"titulo":"Fondo Nacional del Ganado","texto":"Cuota de fomento invertida en sanidad, ciencia y consumo.","imagen":"/locales/fng.jpg","enlace":"/seccion/fng","boton":"Conocer"},{"titulo":"Fondo de Estabilización (FEP)","texto":"Exportaciones de carne, leche y derivados.","imagen":"/headers/campo.jpg","enlace":"/seccion/fep","boton":"Conocer"},{"titulo":"Fundagán","texto":"Ganadería y derechos humanos, y responsabilidad social.","imagen":"/locales/publicaciones.jpg","enlace":"/seccion/programas/programa/fundagan","boton":"Conocer"}]}},{"t":"callout","data":{"titulo":"Conozca el directorio del portal o escríbanos","texto":"Cada servicio, medio y línea de valor del ecosistema tiene su propio espacio.","boton":"Directorio","enlace":"/directorio","tono":"verde"}}]$json$::jsonb, true, 0, true
